guided.solution:
def mask(secret):
    return "*" * max(len(secret) - 2, 0) + secret[-2:]

def redact_headers(headers):
    secret_names = {"x-api-key", "authorization"}
    return {k: mask(v) if k.lower() in secret_names else v for k, v in headers.items()}

print(sorted(redact_headers({"x-api-key": "abcdef", "Accept": "application/json", "Authorization": "Bearer tok-1"}).items()))

