guided.solution:
def explain(status):
    if status == 401:
        return "fix the credential"
    if status == 403:
        return "ask for permission"
    if status // 100 == 2:
        return "ok"
    return "other"

print(" | ".join(explain(s) for s in [200, 401, 403, 404]))

